import 'package:pulumi/pulumi.dart';
import 'app_cookie_stickiness_policy_args.dart';

/// Provides an application cookie stickiness policy, which allows an ELB to wed its sticky cookie's expiration to a cookie generated by your application.
///
/// ## Example Usage
///
///
///
/// ## Import
///
/// Using `pulumi import`, import application cookie stickiness policies using the ELB name, port, and policy name separated by colons (`:`). For example:
///
/// ```sh
/// $ pulumi import aws:elb/appCookieStickinessPolicy:AppCookieStickinessPolicy example my-elb:80:my-policy
/// ```
class AppCookieStickinessPolicy extends CustomResource {
  /// Application cookie whose lifetime the ELB's cookie should follow.
  late final Output<String> cookieName;

  /// Load balancer port to which the policy
  /// should be applied. This must be an active listener on the load
  /// balancer.
  late final Output<int> lbPort;

  /// Name of load balancer to which the policy
  /// should be attached.
  late final Output<String> loadBalancer;

  /// Name of the stickiness policy.
  late final Output<String> name;

  /// Region where this resource will be [managed](https://docs.aws.amazon.com/general/latest/gr/rande.html#regional-endpoints). Defaults to the Region set in the provider configuration.
  late final Output<String> region;

  AppCookieStickinessPolicy(
    String name, {
    AppCookieStickinessPolicyArgs? args,
    CustomResourceOptions? options,
  }) : super(
          'aws:elb/appCookieStickinessPolicy:AppCookieStickinessPolicy',
          name,
          Input.mapToInputs(args?.toMap() ?? const {}),
          options ?? CustomResourceOptions(),
        ) {
    this.cookieName = registerOutput<String>('cookieName');
    this.lbPort = registerOutput<int>('lbPort');
    this.loadBalancer = registerOutput<String>('loadBalancer');
    this.name = registerOutput<String>('name');
    this.region = registerOutput<String>('region');
  }
}
